"""Report actual currency configurations and measured earned-budget combat results."""
from pathlib import Path
import json
root = Path(__file__).resolve().parents[1]
def load(path): return json.loads((root / path).read_text())
e = load('data/economy.json')
d = load('data/definitions.json')
p = load('data/progression.json')
b = load('docs/m3/baseline_economy.json')
# Currency tables are explicit positive integers, with one matching catalog entry.
assert set(e['research_costs']) == set(p['upgrades'])
assert set(e['unlock_costs']) == set(p['unlocks'])
assert set(e['battle']['construction']) == set(d['turrets'])
assert set(e['battle']['bounties']) == set(d['enemies'])
assert set(e['battle']['ability_costs']) == set(p['abilities'])
assert set(e['objective_rewards']) == set(p['objectives'])
for table in [e['war']['first_clear'], e['battle']['starting_credits'], e['battle']['bounties'], e['battle']['construction'], e['battle']['ability_costs'], e['unlock_costs'], e['objective_rewards']]:
 assert all(type(value) is int and value > 0 for value in table.values())
for costs in e['research_costs'].values():
 assert all(type(value) is int and value > 0 for value in costs)
 assert all(left < right for left,right in zip(costs,costs[1:]))
rows = load('docs/m3/campaign_balance.json')
assert rows[0]['war_balance'] == 0
assert all(r['battle_remaining'] >= 0 and r['war_balance_after'] >= 0 for r in rows)
assert len(rows) == 28 and all(r['victory'] for r in rows[:25])
assert not rows[25]['victory'] and all(r['victory'] for r in rows[26:])
assert all(r['war_reward'] == 100+20*(r['id']-1)+(140 if r['id']==5 else 0) for r in rows[:25])
assert rows[26]['war_reward'] == 84 and rows[27]['war_reward'] == 87
old_income = sum(m['reward'] for m in b['missions']) + sum(b['objectives'].values())
income = sum(e['war']['first_clear'].values()) + sum(e['objective_rewards'].values())
assert income == 8640
spent = sum(r['war_reward'] for r in rows)-rows[-1]['war_balance_after']
all_research = sum(map(sum,e['research_costs'].values()))
all_unlocks = sum(e['unlock_costs'].values())
lines = ['# Measured M3 economy report', '',
'Generated by `python tools/report_m3_economy.py`. Raw [campaign results](campaign_balance.json), [accounting scenarios](economy_scenarios.json) and [fixed-policy comparison](fixed_policy/balance.json) are retained alongside this report.', '',
f'First-pass War Credits: **{old_income} → {income}** ({(1-income/old_income)*100:.1f}% lower), including objectives. First-clear mission rewards: {income-140}; once-only objectives: 140. Replay victories give floor(first-clear × 15%).', '',
f'Connected assisted campaign: **25/25 victories**, no injected credits, ads or preliminary grinding. After an actual undefended defeat at 25, missions 24 and 25 were reconquered for **84 + 87 WC**, preserving research. Total purchases over these 28 deployments: **{spent} WC**; ending bank: **{rows[-1]["war_balance_after"]} WC**.', '',
'The reproducible pilot buys basic research/unlocks through the real purchase API, builds the existing MG/Cannon/Missile layout, prioritizes real threats, switches Standard/AP for the visible target, and may spend its actual BC on repair, EMP and overclock. Aim is deterministic assisted input, not gameplay auto-aim. Ammunition switches pay the ordinary cooldown and never refill. It does not prove a human win rate or Android handling. This policy differs from M2; income curves are directly comparable, combat outcomes are not a controlled before/after skill comparison.', '',
'## Every first-clear mission', '',
'BC bounty ceiling counts configured waves only: assumes every enemy killed, excludes optional carrier/boss support and rejects breached-drone rewards. Actual earnings may include support or lose bounties to breaches. Starting supply excludes permanent +50-per-level research.', '',
'| Mission | Start BC | Wave bounty ceiling | Actual bounty / BC spent / ending BC | First / replay WC | End HP |',
'| --- | ---: | ---: | ---: | ---: | ---: |']
for m,r in zip(d['missions'],rows[:25]):
 i=m['id']; cap=sum(g['count']*e['battle']['bounties'][g['enemy']] for w in m['waves'] for g in w['groups']); first=e['war']['first_clear'][str(i)]
 lines.append(f'| {i:02} | {e["battle"]["starting_credits"][str(i)]} | {cap} | {r["battle_earned"]} / {r["battle_spent"]} / {r["battle_remaining"]} | {first} / {first*15//100} | {r["health"]} |')
lines += ['', '## Research costs', '',f'All optional research tiers total **{all_research} WC** and all unlocks total **{all_unlocks} WC**. A first pass deliberately cannot max every branch. No mission requires buying the entire tree.', '', '| Research | Tier/level costs (WC) | Total |', '| --- | --- | ---: |']
for k,c in e['research_costs'].items(): lines.append(f'| {p["upgrades"][k]["name"]} | '+ ' / '.join(map(str,c))+f' | {sum(c)} |')
lines += ['', '## Observed tuning issue and correction', '',
'The first candidate used Scout/Assault/Heavy bounties 6/12/35 and a 0.75 construction-cost multiplier for temporary upgrades. An earned-budget run failed at mission 18. Changing the pilot to an EMP tower in every second slot also failed earlier, at 11: support cannot replace damage everywhere. The final candidate uses 7/13/40 bounties and preserves the existing 0.65 multiplier. A target-aware Standard/AP policy and paid tactical abilities establish the reported no-ad path. These refinements retain pressure without mandatory farming. See [ECONOMY_BALANCE.md](../../ECONOMY_BALANCE.md) for player-facing guidance and remaining human testing.']
(root/'docs/m3/REPORT.md').write_text('\n'.join(lines)+'\n')
print(f'M3 report validated: 25 first clears, defeat/reconquest, {income} WC income, {spent} WC purchases, {rows[-1]["war_balance_after"]} WC bank')
